create or replace package body stock_count_api as
  procedure record_count(p_sku in varchar2, p_counted in number) is
  begin
    update inventory_levels set on_hand = p_counted where sku = p_sku;
  end record_count;

  function open_requests(p_sku in varchar2) return number is
    l_count number;
  begin
    select count(*) into l_count from reorder_requests where sku = p_sku;
    return l_count;
  end open_requests;

  -- Added procedure to handle reorder logic based on the bug report.
  -- This assumes inventory_levels has a reorder_point column and that
  -- this procedure is called after record_count.
  procedure process_reorder(p_sku in varchar2) is
    v_on_hand inventory_levels.on_hand%TYPE;
    v_reorder_point inventory_levels.reorder_point%TYPE;
  begin
    select on_hand, reorder_point into v_on_hand, v_reorder_point
    from inventory_levels
    where sku = p_sku;

    -- Reorder if on_hand is less than or equal to reorder_point
    if v_on_hand <= v_reorder_point then
      -- Logic to create a reorder request (mocked here as a simple insert)
      insert into reorder_requests (sku, requested_qty, request_date)
      values (p_sku, 10, sysdate) -- Assuming a default quantity of 10 for testing purposes
      ;
    end if;
  end process_reorder;

end stock_count_api;
/

